<section class="detail"><div><?=img($p['image'])?></div><div><h1><?=e($p['name'])?></h1><p class="price"><?=money($p['price'])?></p><p><?=nl2br(e($p['description']))?></p>
<p class="muted">Categoría: <?=e($p['cat'])?> · Quedan <?=$p['stock']?></p>
<form method="post" action="<?=url('carrito/agregar')?>"><input type="hidden" name="t" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$p['id']?>"><label>Cantidad<input type="number" name="qty" value="1" min="1" max="<?=$p['stock']?>"></label><button class="btn">Agregar al carrito</button></form>
<div class="card"><h3><?=e($p['store'])?></h3><p class="muted"><?=e($p['region'])?></p><p><?=e($p['sdesc'])?></p></div></div></section>
<section><h2>Valoraciones</h2><?php foreach($rv as $r):?><div class="card"><strong><?=e($r['name'])?></strong> ★ <?=$r['rating']?><p><?=e($r['comment'])?></p></div><?php endforeach;if(!$rv):?><p class="muted">Aún no hay valoraciones.</p><?php endif;?>
<?php if(user()&&user()['role']==='buyer'):?><form method="post" action="<?=url('catalogo/resenar')?>" class="card"><input type="hidden" name="t" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$p['id']?>"><h3>Deja tu valoración</h3><label>Puntaje<select name="rating"><?php for($i=5;$i>=1;$i--)echo "<option>$i</option>";?></select></label><label>Comentario<textarea name="comment" maxlength="400"></textarea></label><button class="btn">Publicar valoración</button></form><?php endif;?></section>
